    '賈詡':[0,1],'曹操':[1,1],'荀彧':[0,1],'張角':[2,3],'崔琰':[1,1],'袁紹':[0,1],'曹叡':[0,1],'曹丕':[1,2],'張遼':[0,1],'羊祜':[1,1],'徐晃':[0,1],'張紘':[1,1],'魏延':[0,1],'王允':[1,1],
    '黃忠':[1,1],'周胤':[0,1],'郭嘉':[1,1],'伊籍':[1,1],'董卓':[2,2],'華雄':[2,2],'太史慈':[2,2],'張飛':[4,6],'劉諶':[0,2],'許褚':[0,2],'顏良&文醜':[1,1]};
