     曹仁 (棄牌階段後展示手牌, 全同色則抽 2 張再重複): 出牌階段盡量打掉少數顏色的牌, 棄牌時先棄少數顏色 */
  const gid=()=>B.history.length;
  const COL=(c)=>{ const x=c&&(c.color||(c.text||'')[0]); return x==='紅'||x==='黑'?x:null; };

  // ---------- 魯肅 ----------
