  function luProtected(m,H){ const hasFj=H.has(m,'發憤圖強')>0; return (c)=>{ const n=H.full(c); return n==='偽裝'||n==='發憤圖強'||(hasFj&&COMBO.test(n)); }; }
  function luDecide(s,p,H){
