      else pick=opts.slice().sort((a,b)=>pl(b).hp-pl(a).hp)[0];
      H.L('魯肅: 交牌對象 → P'+H.pIdx(pick)+(ally.length?' (隊友)':' (全是敵人, 給血最多的)'));
