  // ---------- 周倉 ----------
  function reachSha(s,m,e,H){
    const al=s.players.filter((q)=>q.alive); const a=al.findIndex((q)=>q.idx===m.idx), b=al.findIndex((q)=>q.idx===e.idx); if(a<0||b<0) return false;
    if(m.char==='孫策'||m.char==='顏良&文醜') return true;
