  function wantColor(hand,H){ const sum={紅:0,黑:0}; hand.forEach((c)=>{ const k=COL(c); if(k) sum[k]+=H.keepVal(c)+1; }); return sum.紅>=sum.黑?'紅':'黑'; }
  const SELF_OK=/^(無中生有|增兵減灶|未雨綢繆)$/, ENEMY_OK=/殺$|^(順手牽羊|過河拆橋|樂不思蜀|兵糧寸斷|降雷|火攻|笑裡藏刀|突襲|拋磚引玉)$/;
