async function(){ const B=window.SGSBOT;
  /* b37 (2026-11-02, 使用者回報: 武將系統更新, 技能文字寫「可以」的 (v1.9.0) 對真人多了一個「〈技能〉: 要發動嗎?」詢問;
     機器人是真人座位, 預設一律回「不發動」, 蔣幹別人抽牌階段抽 2 張就不會發動 (電腦座位照舊一律發動))
     規則: 這些「可以」技能舊版都是自動發動, 對自己沒有壞處 → 一律選「發動」 (所有武將, 最外層; 偽裝 / 複製技能也吃得到)
     另外補兩個舊的、機器人一直漏掉的純好處詢問: 崔琰-再抽2張 / 龐統-浴火 (瀕死復活)
     劉備-仁救 X: 自己或非敵人瀕死才發動
     其他舊詢問 (曹彰 / 劉諶 / 許褚 / 貫石斧 / 周倉 / 沮授 ...) 不動, 照原本邏輯 */
  const MAY=['孫堅-棄牌','孫堅-奪牌','魏延-抽牌','曹仁-展示','孟獲-獲得','司馬昭-判定','曹洪-判定','張嶷-同顯','邯鄲淳-判定',
    '太史慈-再抽','蔣幹-趁機抽牌','李嚴-抽牌','李嚴-延時','郭圖&逢紀-變身','司馬炎-抽牌','魯肅-贈牌','崔琰-再抽2張','龐統-浴火'];
  B.mayLog=B.mayLog||{};
  (B.roster||[]).forEach((c)=>{ B.layer(c,{
    decide(s,p,H){ try{ if(p.kind!=='skill') return null; const mt=/^(.+?): 要發動嗎\?/.exec(p.prompt||''); if(!mt) return null;
      const name=mt[1]; const y=(p.options||[]).find((o)=>/^發動|^使用|^是/.test(o.label||'')); if(!y) return null;
      if(/^劉備-仁救/.test(name)){ const mi=/P(\d)/.exec(name); if(!mi) return null; const i=+mi[1];
        const en=new Set(H.enemies(s).map((q)=>q.idx!=null?q.idx:s.players.indexOf(q)));
        if(i===s.viewer||!en.has(i)){ B.mayLog[name]=(B.mayLog[name]||0)+1; H.L('技能詢問: '+name+' → 發動'); return [y.i]; } return null; }
      if(MAY.indexOf(name)<0) return null;
      B.mayLog[name]=(B.mayLog[name]||0)+1; H.L('技能詢問: '+name+' → 發動'); return [y.i]; }catch(e){ return null; } } }); });
  return 'patch b37 loaded (「可以」類技能詢問一律發動: '+MAY.length+' 種 + 劉備仁救)'; }

