  const rec=(n)=>{ const b=REC[n]||[0,0], l=live[n]||[0,0]; return [b[0]+l[0], b[1]+l[1]]; };
  const prior=(n)=>{ const i=SURV.indexOf(n); if(i>=0) return 0.72-0.01*i; const t=TIER[n]; return 0.5+0.0029*((t!=null?t:62)-62); };
